"""Assemble the audit from independently checked data and manually assessed evidence.
Does not fetch sources or alter release files. Evidence access date is fixed to the audit.
Run check_policy_data.py first. All outputs stay in audit/.
"""
from pathlib import Path
import csv,json
from collections import Counter
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'audit'; DATA=ROOT/'data/policy_timeline'
DATE='2026-10-31'
def read(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def csvout(name,rows):
    with (OUT/name).open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
def line(file,needle):
    for i,s in enumerate((ROOT/file).read_text(encoding='utf-8-sig').splitlines(),1):
        if needle in s:return f'{file}:{i}'
    raise ValueError((file,needle))
def table(headers,rows):
    def esc(v):return str(v if v is not None else '').replace('|',' / ').replace('\n',' ')
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(esc,r))+' |' for r in rows])+'\n'
S={}
def source(key,url,locator,note,access='Official indexed text; full-page access not asserted'):
    S[key]=dict(source_id=key,url=url,section=locator,access_date=DATE,access=access,evidence_summary=note)
